<?php
namespace App\Http\Controllers\Api\V1;

use App\Http\Requests\MfaCodeRequest; use App\Http\Requests\PhaseTwoRegisterRequest; use App\Models\Merchant; use App\Models\PlatformAdminMembership; use App\Models\User; use App\Services\AuditLogger; use App\Services\CountryEligibilityService; use App\Services\MfaService; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Hash; use Illuminate\Validation\ValidationException;

final class AuthController {
    public function register(PhaseTwoRegisterRequest $request, CountryEligibilityService $eligibility): JsonResponse { $country=strtoupper($request->string('country_code')->toString()); $eligibility->assertRegistrationAllowed($country); $user=DB::transaction(function() use($request,$country): User { $user=User::create(['name'=>$request->string('name'),'email'=>$request->string('email'),'password'=>$request->string('password'),'country_code'=>$country,'phone_e164'=>$request->string('phone_e164'),'account_status'=>'pending_email','user_type'=>'customer']); $user->customerProfile()->create(['phone'=>$request->string('phone_e164'),'locale'=>'en']); return $user; }); app(AuditLogger::class)->record('customer.registered',$request,['user_id'=>$user->id,'country_code'=>$country]); return response()->json(['data'=>['id'=>$user->id,'email'=>$user->email,'status'=>$user->account_status],'message'=>'If registration is available, verification instructions will be sent.'],201); }
    public function merchantRegister(PhaseTwoRegisterRequest $request, CountryEligibilityService $eligibility): JsonResponse { $country=strtoupper($request->string('country_code')->toString()); $eligibility->assertRegistrationAllowed($country); $user=DB::transaction(function() use($request,$country): User { $user=User::create(['name'=>$request->string('name'),'email'=>$request->string('email'),'password'=>$request->string('password'),'country_code'=>$country,'phone_e164'=>$request->string('phone_e164'),'account_status'=>'pending_email','user_type'=>'merchant']); $merchant=Merchant::create(['legal_name'=>$request->string('name')->toString(),'display_name'=>$request->string('name')->toString(),'status'=>'pending']); DB::table('merchant_memberships')->insert(['merchant_id'=>$merchant->id,'user_id'=>$user->id,'role'=>'owner','created_at'=>now(),'updated_at'=>now()]); return $user; }); app(AuditLogger::class)->record('merchant.registered',$request,['user_id'=>$user->id]); return response()->json(['data'=>['id'=>$user->id,'email'=>$user->email,'status'=>$user->account_status],'message'=>'If registration is available, verification instructions will be sent.'],201); }
    public function login(Request $request, AuditLogger $audit): JsonResponse { $credentials=$request->validate(['email'=>['required','email'],'password'=>['required','string']]); $user=User::where('email',$credentials['email'])->first(); if(!$user || $user->user_type==='staff' || !Hash::check($credentials['password'],$user->password) || !$user->is_active){$audit->record('auth.login_failed',$request); throw ValidationException::withMessages(['email'=>'Unable to sign in with those details.']);} auth()->guard('web')->login($user); $request->session()->regenerate(); $user->loginActivities()->create(['event'=>'login_success','ip_address'=>$request->ip(),'user_agent'=>$request->userAgent(),'occurred_at'=>now()]); $audit->record('auth.login_succeeded',$request); return response()->json(['data'=>['user'=>$user,'mfa_required'=>false],'message'=>'Authenticated.']); }
    public function adminLogin(Request $request, AuditLogger $audit, MfaService $mfa): JsonResponse { $credentials=$request->validate(['email'=>['required','email'],'password'=>['required','string']]); $user=User::where('email',$credentials['email'])->first(); $staff=$user && $user->user_type==='staff' && PlatformAdminMembership::where('user_id',$user->id)->where('status','active')->whereHas('role',fn($query)=>$query->whereIn('name',['platform_super_admin','compliance_admin','finance_operations','risk_analyst','support_agent','read_only_auditor']))->exists(); if(!$user || !Hash::check($credentials['password'],$user->password) || !$user->is_active || !in_array($user->account_status,['active','pending_email'],true) || !$staff){$audit->record('admin.login_failed',$request); throw ValidationException::withMessages(['email'=>'Unable to sign in with those details.']);} if(!$user->hasVerifiedEmail()){ $audit->record('admin.email_verification_required',$request,['user_id'=>$user->id]); return response()->json(['message'=>'Administrator email verification is required.','email_verification_required'=>true],403); } if(!$mfa->enabled($user)){ auth()->guard('web')->login($user); $request->session()->regenerate(); $request->session()->put('platform_admin_mfa_enrollment', true); $audit->record('admin.mfa_required',$request,['user_id'=>$user->id]); return response()->json(['message'=>'Administrator MFA enrollment is required.','mfa_required'=>true,'enrollment_required'=>true],403); } $request->session()->regenerate(); $request->session()->put(['platform_admin_mfa_pending_user_id'=>$user->id,'platform_admin_mfa_pending_until'=>now()->addMinutes(5)->toIso8601String()]); $audit->record('admin.mfa_challenge_required',$request,['user_id'=>$user->id]); return response()->json(['message'=>'Administrator MFA verification is required.','mfa_required'=>true,'challenge_required'=>true],403); }
    public function adminMfaVerify(Request $request, MfaCodeRequest $codeRequest, MfaService $mfa, AuditLogger $audit): JsonResponse { $pendingId=$request->session()->get('platform_admin_mfa_pending_user_id'); $pendingUntil=$request->session()->get('platform_admin_mfa_pending_until'); abort_unless($pendingId && $pendingUntil && now()->lt($pendingUntil),422,'The administrator MFA challenge has expired. Sign in again.'); $user=User::findOrFail($pendingId); $staff=$user->user_type==='staff' && $user->is_active && $user->account_status==='active' && $user->hasVerifiedEmail() && PlatformAdminMembership::where('user_id',$user->id)->where('status','active')->whereHas('role',fn($query)=>$query->whereIn('name',['platform_super_admin','compliance_admin','finance_operations','risk_analyst','support_agent','read_only_auditor']))->exists(); abort_unless($staff,403,'Platform administrator access is no longer available.'); abort_unless($mfa->verifyChallenge($user,$codeRequest->string('code')->toString()),422,'Invalid MFA code.'); auth()->guard('web')->login($user); $request->session()->regenerate(); $request->session()->forget(['platform_admin_mfa_pending_user_id','platform_admin_mfa_pending_until']); $request->session()->put('platform_admin_authenticated_at',now()->toIso8601String()); $audit->record('admin.login_succeeded',$request,['user_id'=>$user->id,'mfa'=>'totp']); return response()->json(['data'=>['user'=>$user,'mfa_required'=>true]]); }
    public function resendAdminVerification(Request $request, AuditLogger $audit): JsonResponse { $data=$request->validate(['email'=>['required','email']]); $user=User::whereRaw('LOWER(email) = ?', [strtolower($data['email'])])->where('user_type','staff')->where('is_active',true)->whereHas('platformAdminMemberships',fn($query)=>$query->where('status','active'))->first(); if($user && !$user->hasVerifiedEmail()) { $user->sendEmailVerificationNotification(); $audit->record('admin.verification_resent',$request,['user_id'=>$user->id]); } else { $audit->record('admin.verification_resend_requested',$request); } return response()->json(['message'=>'If an eligible administrator account matches, verification instructions will be sent.']); }
    public function me(Request $request): JsonResponse { return response()->json(['data'=>$request->user()]); }
    public function logout(Request $request, AuditLogger $audit): JsonResponse { if($request->user()) $request->user()->loginActivities()->create(['event'=>'logout','ip_address'=>$request->ip(),'user_agent'=>$request->userAgent(),'occurred_at'=>now()]); auth()->guard('web')->logout(); $request->session()->invalidate(); $request->session()->regenerateToken(); $audit->record('auth.logout',$request); return response()->json(['message'=>'Signed out.']); }
    public function mfaStatus(Request $request, MfaService $mfa): JsonResponse { return response()->json(['data'=>['enabled'=>$mfa->enabled($request->user())]]); }
    public function mfaEnroll(Request $request, MfaService $mfa): JsonResponse { return response()->json(['data'=>$mfa->begin($request->user())]); }
    public function mfaVerify(MfaCodeRequest $request, MfaService $mfa): JsonResponse { return response()->json(['data'=>$mfa->verify($request->user(),$request->string('code')->toString())]); }
    public function mfaRecovery(MfaCodeRequest $request, MfaService $mfa): JsonResponse { abort_unless($mfa->verifyRecoveryCode($request->user(),$request->string('code')->toString()),422,'Invalid or already used recovery code.'); return response()->json(['message'=>'Recovery code accepted.']); }
}
